      fonte(d, 'B4', 8); var ol = s.obs ? d.splitTextToSize(T(d, s.obs), col.nomeW) : [];
      var hl = Math.max(2.4 + nl.length * 4.15 + ol.length * 3.6 + 2.2, pct(s.ate) >= 100 && pct(s.de) < 100 ? 10.6 : 0);
