      doc.setPage(pos.pg);
      if (i % 2) { cor(d, 'f', C.papel2); d.rect(MX, pos.y, CW, lh, 'F'); }
      var cl = climaCurto(r), tot = (r.equipe || []).reduce(function (s, x) { return s + (Number(x.n) || 0); }, 0);
      var yt = pos.y + 4.2;
      fonte(d, 'C7', 9, C.verde); d.text(T(d, String(r.codigo || '—')), cols[0][0], yt);
      fonte(d, 'B6', 8.6, C.texto); d.text(ddmmaa(r.dia) + ' ' + semCurta(r.dia), cols[1][0], yt);
      fonte(d, 'B4', 8.6, engenheiro(r) ? C.texto : C.texto3); d.text(d.splitTextToSize(T(d, engenheiro(r) || 'não informado'), 42)[0] || '', cols[2][0], yt);
      fonte(d, 'B6', 8.6, C.texto); d.text(tot ? String(tot) : '—', cols[3][0], yt, { align: 'right' });
      fonte(d, 'B4', 8.4, cl.impr ? C.critico : C.texto2);
